  .filter((block) => block && String(block.type ?? '').endsWith('_tool_result'))
  .filter((block) => !Array.isArray(block.content))
  .map((block) => String(block.content?.error_code ?? 'unknown'));

const sorted = $('Sort Candidates').first().json;
const responses = $input.all().map((item) => item.json).filter((item) => typeof item.statusCode === 'number');

const verified = [];
const dropped = [];
let inputTokens = 0;
let outputTokens = 0;

// A node that runs once per item emits results in input order, so the
// shortlist entry at index i belongs to the response at index i.
for (let index = 0; index < responses.length; index += 1) {
  const candidate = sorted.shortlist[index];
  if (!candidate) continue;
  const response = responses[index];
  if (Number(response.statusCode) !== 200) {
    dropped.push({ programName: candidate.programName, reason: 'the check could not be completed' });
    continue;
  }
  const body = response.body ?? {};
  inputTokens += Number(body?.usage?.input_tokens ?? 0) || 0;
  outputTokens += Number(body?.usage?.output_tokens ?? 0) || 0;

  const parsed = jsonFrom(textFrom(body));
  if (!parsed) {
    dropped.push({ programName: candidate.programName, reason: 'the check did not return readable JSON' });
    continue;
  }
  if (parsed.pageSupports === false) {
    dropped.push({ programName: candidate.programName, reason: 'its official page does not describe this program' });
    continue;
  }

  const eligibility = Array.isArray(parsed.eligibility)
    ? parsed.eligibility.map((line) => String(line).trim()).filter(Boolean).slice(0, 10)
    : [];

  verified.push({
    ...candidate,
    programName: String(parsed.programName ?? candidate.programName).trim().slice(0, 200) || candidate.programName,
    administeredBy: String(parsed.administeredBy ?? candidate.administeredBy).trim().slice(0, 200),
    amountText: String(parsed.amountText ?? candidate.amountText).trim().slice(0, 200),
    whatItFunds: String(parsed.whatItFunds ?? candidate.whatItFunds).trim().slice(0, 400),
    opensAt: String(parsed.opensAt ?? candidate.opensAt).trim().slice(0, 60),
    closesAt: String(parsed.closesAt ?? candidate.closesAt).trim().slice(0, 60),
    status: ['open', 'opening-soon', 'closing-soon', 'closed', 'unknown'].includes(String(parsed.status))
      ? String(parsed.status) : 'unknown',
    eligibility,
    effort: ['low', 'medium', 'high'].includes(String(parsed.effort)) ? String(parsed.effort) : 'medium',
  });
}

const open = verified.filter((program) => program.status !== 'closed');

return [{ json: {
  ...sorted,
  verified: open,
  droppedInVerification: dropped.concat(
    verified.filter((program) => program.status === 'closed')
      .map((program) => ({ programName: program.programName, reason: 'its official page says the round has closed' })),
  ),
  inputTokens: Number(sorted.inputTokens ?? 0) + inputTokens,
  outputTokens: Number(sorted.outputTokens ?? 0) + outputTokens,
} }];

const hostOf = (value) => {
  let host = String(value ?? '').trim().toLowerCase();
  const scheme = host.match(/^([a-z][a-z0-9+.-]*):\/\//);
  if (scheme) host = ['http', 'https'].includes(scheme[1]) ? host.slice(scheme[0].length) : '';
