const toolErrorsIn = (body) => (Array.isArray(body?.content) ? body.content : [])
  .filter((block) => block && String(block.type ?? '').endsWith('_tool_result'))
  .filter((block) => !Array.isArray(block.content))
  .map((block) => String(block.content?.error_code ?? 'unknown'));

const collected = $('Collect Verified').first().json;
const incoming = $input.first()?.json ?? {};
const judged = typeof incoming.statusCode === 'number' ? incoming : null;

let verdicts = [];
let inputTokens = Number(collected.inputTokens ?? 0);
let outputTokens = Number(collected.outputTokens ?? 0);
let judgeFailed = false;

if (judged) {
  if (Number(judged.statusCode) === 200) {
    const body = judged.body ?? {};
    inputTokens += Number(body?.usage?.input_tokens ?? 0) || 0;
    outputTokens += Number(body?.usage?.output_tokens ?? 0) || 0;
    const parsed = jsonFrom(textFrom(body));
    if (parsed && Array.isArray(parsed.verdicts)) verdicts = parsed.verdicts;
    else judgeFailed = true;
  } else {
    judgeFailed = true;
  }
}

const byIndex = new Map(verdicts.map((verdict) => [Number(verdict.index), verdict]));
const allowed = ['eligible', 'likely', 'unclear', 'not-eligible'];

const findings = collected.verified.map((program, index) => {
  const verdict = byIndex.get(index) ?? {};
  return {
    ...program,
    verdict: allowed.includes(String(verdict.verdict)) ? String(verdict.verdict) : 'unclear',
    verdictReason: String(verdict.verdictReason ?? 'The criteria were not assessed on this run.').slice(0, 400),
    deciderCriterion: String(verdict.deciderCriterion ?? 'Check the eligibility section on the official page.').slice(0, 300),
    priority: Number(verdict.priority ?? 0) || 0,
    eligibilitySummary: (program.eligibility ?? []).join('; ').slice(0, 800),
  };
});

// Not-eligible programs are still stored, so a later search does not
// rediscover and re-verify them, but they never reach the report.
const reportable = findings.filter((finding) => finding.verdict !== 'not-eligible');
reportable.sort((a, b) => b.priority - a.priority);

return [{ json: {
  ...collected,
  findings,
  reportable,
  judgeFailed,
  inputTokens,
  outputTokens,
} }];

const dayIndex = (value) => {
  const text = String(value ?? '').trim();
  const isoDate = text.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (isoDate) return Math.floor(Date.UTC(Number(isoDate[1]), Number(isoDate[2]) - 1, Number(isoDate[3])) / 86400000);
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return null;
  return Math.floor(Date.UTC(parsed.getFullYear(), parsed.getMonth(), parsed.getDate()) / 86400000);
};
const todayIndex = dayIndex(new Date());
const daysUntil = (value) => {
  if (!value) return null;
  const index = dayIndex(value);
  return index === null ? null : index - todayIndex;
};

// Shape Findings holds the search. It does not feed this node directly —
// Load Closing Soon sits between them — so reading $input here picked up a
// stored opportunity row, found no findings array on it, and reported the
// search as blocked for want of a business profile. Every scan ran in full,
// cost its dollar, and then threw the results away and asked the owner for
// details it already had. Name the node.
const fromNode = (name) => { try { return $(name).first().json; } catch { return null; } };
const incoming = fromNode('Shape Findings') ?? {};
const context = $('Check Profile').first().json;
const now = new Date();
const stamp = now.toISOString();
const pad = (value) => String(value).padStart(2, '0');
// Header shows the owner's calendar date; ranAt stays a UTC timestamp.
const localDate = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;

// The chat window renders plain text, so no markdown tables, no hashes,
// and no bold markers: they arrive as literal characters.
const lines = [];

if (!Array.isArray(incoming.findings)) {
  const diagnostic = context.diagnostic ?? {};
  const savedButUnreadable = Number(diagnostic.nonEmptyRows ?? 0) > 0 || Number(diagnostic.matchedProfileRow ?? 0) > 0;
  if (savedButUnreadable) {
    lines.push(`Funding scan — ${localDate}`);
    lines.push('');
    lines.push('I did not search, because I could not read the business details that are saved.');
    lines.push('');
    lines.push('That is a fault on my side, not anything missing from you. Nothing was lost and nothing was charged. Please pass this line on to whoever set the agent up:');
    lines.push(`  profile read: ${JSON.stringify(diagnostic)}`);
    return [{ json: {
      reportText: lines.join('\n'), status: 'failed', ranAt: stamp,
      runId: context.runId,
      beatsAttempted: 0, beatsSucceeded: 0, candidatesFound: 0,
      newCount: 0, changedCount: 0, closingSoonCount: 0, searchCount: 0,
      inputTokens: 0, outputTokens: 0,
      errorSummary: `profile unreadable: ${JSON.stringify(diagnostic)}`.slice(0, 900),
      findings: [],
    } }];
  }
  lines.push(`Funding scan — ${localDate}`);
  lines.push('');
  lines.push('I could not search, because I do not know enough about the business yet.');
  lines.push('');
  lines.push('Eligibility is decided by things I do not otherwise hold: what kind of entity it is, which state it is registered in, how many people work there, and roughly what it turns over.');
  lines.push('');
  lines.push('Tell me those in the chat and I will save them, then ask me to look for funding again.');
  return [{ json: {
    reportText: lines.join('\n'), status: 'blocked', ranAt: stamp,
    runId: context.runId,
    beatsAttempted: 0, beatsSucceeded: 0, candidatesFound: 0,
    newCount: 0, changedCount: 0, closingSoonCount: 0, searchCount: 0,
    inputTokens: 0, outputTokens: 0,
    errorSummary: 'No funding profile saved.', findings: [],
  } }];
}

const closingSoon = $('Load Closing Soon').all().map((item) => item.json)
  .filter((row) => row && row.fingerprint && String(row.dismissed ?? '') !== 'yes')
  .filter((row) => !incoming.reportable.some((finding) => finding.fingerprint === row.fingerprint))
  .map((row) => ({ ...row, daysLeft: daysUntil(row.closesAt) }))
  .filter((row) => row.daysLeft !== null && row.daysLeft >= 0 && row.daysLeft <= 14)
  .sort((a, b) => a.daysLeft - b.daysLeft)
  .slice(0, 5);

const shown = incoming.reportable.slice(0, 5);
const newCount = shown.filter((finding) => finding.change === 'new').length;
const changedCount = shown.filter((finding) => finding.change === 'changed').length;

lines.push(`Funding scan — ${localDate}`);
lines.push('');

if (context.staleDays !== null && context.staleDays > 90) {
  lines.push(`Note: this is based on a business profile last updated ${context.staleDays} days ago. If headcount, turnover, or location has changed, tell me and I will redo it.`);
  lines.push('');
}

const headline = [];
if (newCount > 0) headline.push(`${newCount} new`);
if (changedCount > 0) headline.push(`${changedCount} changed`);
if (closingSoon.length > 0) headline.push(`${closingSoon.length} closing soon`);
lines.push(headline.length > 0 ? `${headline.join(', ')}.` : 'Nothing new today.');
lines.push('');

if (shown.length > 0) {
  lines.push(shown.some((finding) => finding.change === 'changed') ? 'NEW AND CHANGED' : 'NEW');
  shown.forEach((finding, index) => {
    const left = daysUntil(finding.closesAt);
    lines.push(`${index + 1}. ${finding.programName}${finding.amountText ? ' — ' + finding.amountText : ''}`);
    if (finding.administeredBy) lines.push(`   Who runs it: ${finding.administeredBy}`);
    if (finding.whatItFunds) lines.push(`   For: ${finding.whatItFunds}`);
    if (finding.closesAt) {
      lines.push(`   Closes: ${finding.closesAt}${left !== null && left >= 0 ? ' (' + left + ' days)' : ''}`);
    } else {
      lines.push('   Closes: not stated on the page');
    }
    if (finding.change === 'changed' && finding.previous) {
      lines.push(`   Changed since I last looked: was closing ${finding.previous.closesAt || 'unstated'}, amount was ${finding.previous.amountText || 'unstated'}.`);
    }
    lines.push(`   ${finding.verdictReason}`);
    lines.push(`   What to check yourself: ${finding.deciderCriterion}`);
    if (finding.sourceTrust !== 'official') {
      lines.push('   Found on a third-party site — I could not confirm this on an official page.');
    }
    lines.push(`   ${finding.officialUrl}`);
    lines.push('');
  });
}

if (closingSoon.length > 0) {
  lines.push('CLOSING SOON');
  for (const row of closingSoon) {
    lines.push(`- ${row.programName} closes in ${row.daysLeft} days. I first flagged it on ${String(row.firstSeenAt ?? '').slice(0, 10)}.`);
  }
  lines.push('');
}

const checked = (incoming.beatsRun ?? []).filter((beat) => !(incoming.failedBeats ?? []).some((failed) => failed.beat === beat));
// A beat whose web search never ran still answers, and it answers with an
// empty list. Reported as "I checked those sources", that is a confident
// claim about work that did not happen, and it reads exactly like good news.
// Count the searches the API says it ran before claiming to have looked.
const searchCount = Number(incoming.searchCount ?? 0);
const toolErrors = incoming.toolErrors ?? [];
const considered = Number(incoming.considered ?? 0);
const rejected = incoming.rejected ?? [];
const tally = (entries) => {
  const counts = new Map();
  for (const entry of entries) {
    const reason = String(entry?.reason ?? '').trim() || 'no reason given';
    counts.set(reason, (counts.get(reason) ?? 0) + 1);
  }
  return [...counts.entries()].sort((a, b) => b[1] - a[1]).map(([reason, n]) => `${n} ${reason}`);
};
const searchedNothing = searchCount === 0 && Number(incoming.beatsSucceeded ?? 0) > 0;

if (searchedNothing) {
  lines.push('I could not search the web on this run, so I have nothing to report.');
  lines.push('');
  lines.push('This is not the same as there being no funding for you. My search came back without having looked. Nothing is wrong at your end, and there is nothing you need to fix or tell me. Ask me to search again in a few minutes.');
  lines.push('');
} else if (shown.length === 0 && closingSoon.length === 0) {
  lines.push(`I ran ${searchCount} ${searchCount === 1 ? 'search' : 'searches'} across ${checked.length > 0 ? checked.join(', ') : 'no'} sources and found nothing new.`);
  lines.push('');
  // "Nothing new" covers two very different days: everything I saw was closed,
  // and I saw nothing at all. Only the second one means the search is broken,
  // and until now the report said the same words for both.
  if (rejected.length > 0) {
    lines.push(`I looked at ${Math.max(considered, rejected.length)} programs and set all of them aside: ${tally(rejected).join(', ')}.`);
  } else if (considered > 0) {
    lines.push(`I looked at ${considered} programs and none of them came through, though I was not told why.`);
  } else {
    lines.push('The searches came back without a single program to look at. That is unusual enough to be worth saying: it points at my search rather than at how little is on offer.');
  }
  lines.push('');
} else if (checked.length > 0) {
  lines.push(`Checked: ${checked.join(', ')}.`);
  lines.push('');
}

const notes = [];
for (const failed of incoming.failedBeats ?? []) {
  notes.push(`I could not reach the ${failed.beat} sources today.`);
}
for (const entry of rejected.slice(0, 5)) {
  notes.push(`Set aside: ${entry.programName || 'a program it did not name'} — ${entry.reason}.`);
}
if (toolErrors.length > 0) {
  notes.push(`${toolErrors.length} web searches failed outright (${[...new Set(toolErrors)].join(', ')}), so this run saw less of the web than it should have.`);
}
if (incoming.judgeFailed) notes.push('I could not assess eligibility on this run, so the verdicts above are placeholders.');
if (incoming.skippedForBudget > 0) notes.push(`${incoming.skippedForBudget} more programs are waiting to be checked; I check four per search and will pick them up next time.`);
for (const dropped of incoming.droppedInVerification ?? []) {
  notes.push(`I dropped "${dropped.programName}" because ${dropped.reason}.`);
}
if (notes.length > 0) {
  lines.push('NOTES');
  for (const note of notes) lines.push(`- ${note}`);
  lines.push('');
}

lines.push('Ask me for this again any time and I will read it straight back — I do not go looking again unless you ask.');
lines.push('');
lines.push('I find and report. I never apply for anything, and I never contact the people running these programs — that part is yours.');

const status = incoming.beatsSucceeded === 0 || searchedNothing
  ? 'failed'
  : (incoming.failedBeats ?? []).length > 0 || incoming.judgeFailed || toolErrors.length > 0 ? 'partial' : 'ok';

return [{ json: {
  reportText: lines.join('\n'),
  status,
  runId: context.runId,
  ranAt: stamp,
  beatsAttempted: Number(incoming.beatsAttempted ?? 0),
  beatsSucceeded: Number(incoming.beatsSucceeded ?? 0),
  candidatesFound: (incoming.candidates ?? []).length,
  newCount,
  changedCount,
  closingSoonCount: closingSoon.length,
  searchCount: Number(incoming.searchCount ?? 0),
  inputTokens: Number(incoming.inputTokens ?? 0),
  outputTokens: Number(incoming.outputTokens ?? 0),
  errorSummary: [
    ...(incoming.failedBeats ?? []).map((failed) => `${failed.beat}: ${failed.error}`),
    ...(toolErrors.length > 0 ? [`web search errors: ${toolErrors.join(',')}`] : []),
    ...(searchedNothing ? ['no web searches ran'] : []),
  ].join(' | ').slice(0, 900),
  findings: incoming.findings ?? [],
  reportedFingerprints: shown.map((finding) => finding.fingerprint),
} }];
